// Unione automatica di DATABASE_ARMI_FILE in SRD_OGGETTI e SAMPLE_DATA (senza duplicati)
(function() {
  var existingIds = {};
  var existingNames = {};
  SRD_OGGETTI.forEach(function(item) {
    if (item.id) existingIds[item.id] = true;
    if (item.nome) existingNames[item.nome.trim().toLowerCase()] = item;
  });
  if (Array.isArray(DATABASE_ARMI_FILE)) {
    DATABASE_ARMI_FILE.forEach(function(item) {
      if (!item || !item.nome) return;
      var k = item.nome.trim().toLowerCase();
      if (!existingNames[k] && (!item.id || !existingIds[item.id])) {
        SRD_OGGETTI.push(item);
        if (item.id) existingIds[item.id] = true;
        existingNames[k] = item;
      } else if (existingNames[k] && item.immagine && (!existingNames[k].immagine || item.immagine.indexOf("img/") === 0)) {
        existingNames[k].immagine = item.immagine;
      }
    });
  }
  // Unione di DATABASE_BESTIARIO_FILE in SRD_BESTIARIO (senza duplicati)
  var bestNames = {};
  SRD_BESTIARIO.forEach(function(m) {
    if (m.nome) bestNames[m.nome.trim().toLowerCase()] = m;
  });
  if (Array.isArray(DATABASE_BESTIARIO_FILE)) {
    DATABASE_BESTIARIO_FILE.forEach(function(m) {
      if (!m || !m.nome) return;
      var k = m.nome.trim().toLowerCase();
      if (!bestNames[k]) {
        SRD_BESTIARIO.push(m);
        bestNames[k] = m;
      }
    });
  }
})();
